"""Becky reviews her own network, and reports. It never changes anything.

Three measurements, all on the real model:

* **Where the parameters are**: embeddings vs attention vs MLP vs norms.
* **Where the time goes**: seconds per generated byte with the naive loop vs the cached loop.
* **Which layers matter**: for each transformer block, remove it and re-score on fresh
  examples. A block whose removal costs nothing is a candidate for pruning.

The output is a list of *suggestions*. Applying any of them is a separate decision for you:
pruning, for instance, would mean building and training a smaller brain and checking it with
``brain-eval`` before it replaces anything.
"""

from __future__ import annotations

import copy
import random
import time

import torch

from .brain import OwnLLM, evaluate_brain, make_examples
from .model import GPT


def param_breakdown(model: GPT) -> dict[str, int]:
    out = {"embeddings": 0, "attention": 0, "mlp": 0, "norms": 0, "other": 0}
    seen: set[int] = set()
    for name, p in model.named_parameters():
        if id(p) in seen:  # the tied output head shares the token embedding
            continue
        seen.add(id(p))
        if "emb" in name or name.startswith("head"):
            out["embeddings"] += p.numel()
        elif ".attn." in name:
            out["attention"] += p.numel()
        elif ".mlp." in name:
            out["mlp"] += p.numel()
        elif ".ln" in name or name.startswith("ln_f"):
            out["norms"] += p.numel()
        else:
            out["other"] += p.numel()
    return out


def time_per_byte(brain: OwnLLM, prompts: list[str], naive: bool) -> float:
    """Average seconds per generated byte."""
    fn = brain.complete_naive if naive else brain.complete
    produced, t0 = 0, time.perf_counter()
    for p in prompts:
        produced += max(1, len(fn(p)))
    return (time.perf_counter() - t0) / produced


def layer_importance(model: GPT, eval_n: int, seed: int) -> list[dict]:
    """Accuracy with each block removed, against the intact model on the same examples."""
    base = evaluate_brain(OwnLLM(model), n=eval_n, seed=seed)["overall"]
    rows = []
    for i in range(len(model.blocks)):
        probe = copy.deepcopy(model)
        del probe.blocks[i]
        acc = evaluate_brain(OwnLLM(probe), n=eval_n, seed=seed)["overall"]
        rows.append({"layer": i, "accuracy_without": acc, "cost": base - acc})
    return rows


def review(model: GPT, eval_n: int = 40, speed_prompts: int = 12, seed: int = 2024) -> dict:
    brain = OwnLLM(model)
    params = param_breakdown(model)
    total = sum(params.values())
    prompts = [e.prompt for e in make_examples(random.Random(seed), speed_prompts * 3, "test")][:speed_prompts]
    naive, cached = time_per_byte(brain, prompts, True), time_per_byte(brain, prompts, False)
    layers = layer_importance(model, eval_n, seed)
    base = evaluate_brain(brain, n=eval_n, seed=seed)["overall"]
    used = [len(p) for p in prompts]

    notes: list[str] = []
    big = (params["attention"] + params["mlp"]) / total
    notes.append(f"{big:.0%} of the parameters are in attention and MLP layers, so weight compression "
                 "(`compress`) acts on nearly everything.")
    notes.append(f"Cached decoding is {naive / cached:.1f}x faster per byte than recomputing the context "
                 "(already in use).")
    for row in layers:
        if row["cost"] <= 0.01:
            notes.append(f"Layer {row['layer']} cost only {row['cost']:.1%} accuracy when removed: a candidate "
                         "for pruning. Training a smaller brain and checking it with `brain-eval` would test this.")
    if not any(r["cost"] <= 0.01 for r in layers):
        notes.append("Every layer matters: removing any one costs measurable accuracy, so pruning would hurt.")
    notes.append(f"Prompts use about {sum(used) / len(used) / model.cfg.block_size:.0%} of the "
                 f"{model.cfg.block_size}-byte context before she starts answering.")
    return {"parameters": params, "total_parameters": total, "seconds_per_byte_naive": naive,
            "seconds_per_byte_cached": cached, "speedup": naive / cached, "baseline_accuracy": base,
            "layers": layers, "suggestions": notes}


def render(r: dict) -> str:
    lines = ["Becky's self-review (nothing was changed)", "", f"Parameters: {r['total_parameters']:,}"]
    for k, v in r["parameters"].items():
        if v:
            lines.append(f"  {k:<11}{v:>10,}  {v / r['total_parameters']:>5.0%}")
    lines += ["", f"Speed per generated byte: naive {r['seconds_per_byte_naive'] * 1000:.2f} ms, "
              f"cached {r['seconds_per_byte_cached'] * 1000:.2f} ms  (x{r['speedup']:.1f})", "",
              f"Layer importance (accuracy {r['baseline_accuracy']:.1%} intact):"]
    for row in r["layers"]:
        lines.append(f"  without layer {row['layer']}: {row['accuracy_without']:.1%}  (cost {row['cost']:.1%})")
    lines += ["", "Suggestions (you decide; none applied):"] + [f"  - {s}" for s in r["suggestions"]]
    return "\n".join(lines)
